'use strict';

/**
 * Brings the live 'items' table back in line with the authoritative CSV
 * catalogue (backend/src/scripts/output_with_categories_and_en_v4_slug_from_col5_camel.csv).
 *
 * Generated by diffing a production export against the CSV after the
 * fish/seafood enum was added. 70 items had the wrong category
 * in the database and are corrected here.
 *
 * Idempotent: running it against a database that already matches the CSV
 * is a no-op (bulkUpdate with zero affected rows).
 *
 * No 'down' function: catalog cleanup, not user data
 */

const UPDATES = {
  fish: [
    'anchovy', 'bar', 'bluefinTuna', 'bluefinTunaLoin', 'bonito',
    'bonitoFlakes', 'canOfTunaInOil', 'cod', 'cod2', 'codHeart',
    'codLoin', 'colin', 'driedBonito', 'filletedAndScaledRedMulletFillets', 'freshSalmon',
    'haddock', 'haddock2', 'hake', 'herring', 'mackerel',
    'merluchon', 'norwegianSaithe', 'pollack', 'rayWing', 'redMullet',
    'saithe', 'salmon', 'salmonHeart', 'salmonRoe', 'salmonSteak',
    'salmonTrout', 'salmonette', 'sardine', 'seaBream2', 'skinlessHaddock',
    'smokedSalmon', 'sole', 'solePortion', 'swordfish', 'trout',
    'troutEgg', 'tuna', 'turbot', 'turbotFillet', 'whiteTuna',
  ],
  seafood: [
    'clam', 'crab', 'crabFlakes', 'crabMeat', 'cuttlefish',
    'langoustine', 'lobster', 'lobster2', 'lobsterMeat', 'lobsterTail',
    'mussels', 'oyster', 'periwinkle', 'prawns', 'scallopShell',
    'scallops', 'scallops2', 'scampi', 'seaSpider', 'shells',
    'shrimpPaste', 'shrimpTail', 'squid', 'squid2', 'whelk',
  ],
};

module.exports = {
  async up(queryInterface, Sequelize) {
    const transaction = await queryInterface.sequelize.transaction();
    try {
      for (const [category, names] of Object.entries(UPDATES)) {
        await queryInterface.bulkUpdate(
          'items',
          { category },
          { name: names },
          { transaction }
        );
      }
      await transaction.commit();
    } catch (err) {
      await transaction.rollback();
      throw err;
    }
  },

  async down() {
    // No rollback: catalog reclassification is not reversible by design.
  },
};
